basicCode.vanilla:
import { createComposer } from '@/components/ui/composer';

createComposer({
  labels,
  attachmentLabels,
  attachments: arquivos,
  onRemoveAttachment: (anexo) => remover(anexo.id),
});

basicCode.react:
import { Composer } from "@/components/ui/composer";

<Composer
  labels={labels}
  attachmentLabels={attachmentLabels}
  attachments={arquivos}
  onRemoveAttachment={(anexo) => remover(anexo.id)}
/>

withProgressCode.web:
// O progresso é de quem sobe o arquivo. O componente desenha o que recebe.
{ id: 'a1', name: 'planta.pdf', size: 2516582, state: 'uploading', progress: 0.4 }

// Terminou: o estado muda, e a barra some junto.
{ id: 'a1', name: 'planta.pdf', size: 2516582, state: 'ready' }

extensibilityCode.web:
// O anexo é DADO, e o componente não sabe o que ele significa.
// Quem consome decide o que pode ser anexado, quando sobe e o que fazer
// quando falha.
{
  id: 'a1',
  name: 'planta.pdf',
  mediaType: 'application/pdf',
  size: 2516582,      // convertido por @shared/primitives/file-size
  state: 'failed',    // a palavra vem dos rótulos, e é o que se ouve
}

customizationCode.web:
.nds-composer-attachment {
  max-inline-size: 20rem;
}

/* A barra lê o progresso de uma custom property, e não de largura em estilo
   embutido: o valor é dado de runtime, e a folha decide como ele vira
   desenho. */
.nds-composer-attachment-bar-fill {
  background-color: hsl(var(--primary));
}

